/* @autogenerated */
import { ChangeDetectionStrategy, Component, computed, effect, inject, signal } from '@angular/core';
import { RouterLink } from '@angular/router';
import { MatIconModule } from '@angular/material/icon';
import { TranslocoPipe } from '@jsverse/transloco';
import { Subscription } from 'rxjs';
import { AppStateService } from '@shared/context/state/app-state.service';
import { NavItem } from '../../../workspace/workspace.model';
import { WorkspaceStateService } from '../../../workspace/workspace-state.service';
import { RouteAccessService } from '../../menu/route-accessible.service';

/** Entrada enlazable, con los comandos del router ya resueltos. */
export interface NavLink {
  label: string;
  icon?: string;
  link: string[];
  url: string;
}

/** Grupo del menú con sus entradas visibles; las entradas sueltas del primer nivel van en uno sin título. */
export interface NavGroup {
  label?: string;
  icon?: string;
  links: NavLink[];
}

let nextId = 0;

/**
 * El menú del workspace activo como tarjetas de accesos directos. Muestra lo mismo que la navegación: oculta lo
 * que exige un selector sin valor (o con valor, en `except`) y lo que sus guards no dejarían abrir.
 */
@Component({
  selector: 'app-nav-section',
  standalone: true,
  imports: [MatIconModule, RouterLink, TranslocoPipe],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './nav-section.component.html',
  styleUrl: './nav-section.component.scss',
})
export class NavSectionComponent {
  private readonly workspace = inject(WorkspaceStateService);
  private readonly appState = inject(AppStateService);
  private readonly access = inject(RouteAccessService);

  /** Resultado de los guards por URL; mientras no llega, la entrada no se enseña. */
  private readonly allowed = signal<Record<string, boolean>>({});

  /** Grupos con las entradas que pasan los selectores, antes de mirar los guards. */
  private readonly candidates = computed<NavGroup[]>(() => {
    const contexts = this.appState.contexts();
    // `link()` y `url()` los leen sin seguirlos: al cambiar de idioma o tenant en la portada, los enlaces se rehacen
    this.appState.language();
    this.appState.tenant();
    const fits = (item: NavItem) =>
      (item.requires ?? []).every((key) => present(contexts[key]?.value)) &&
      (item.except ?? []).every((key) => !present(contexts[key]?.value));
    const toLinks = (items: NavItem[]): NavLink[] =>
      items.filter(fits).flatMap((item) => [
        ...(item.route
          ? [
              {
                label: item.label,
                icon: item.icon,
                link: this.workspace.link(item.route),
                url: this.workspace.url(item.route),
              },
            ]
          : []),
        ...toLinks(item.children ?? []),
      ]);

    const nav = this.workspace.nav();
    const loose = nav.filter((item) => !item.children?.length);
    const groups = nav
      .filter((item) => item.children?.length && fits(item))
      .map((item) => ({ label: item.label, icon: item.icon, links: toLinks(item.children!) }));
    return [{ links: toLinks(loose) }, ...groups];
  });

  readonly groups = computed<NavGroup[]>(() => {
    const allowed = this.allowed();
    return this.candidates()
      .map((group) => ({ ...group, links: group.links.filter((link) => allowed[link.url]) }))
      .filter((group) => group.links.length);
  });

  readonly titleId = `nav-title-${nextId++}`;

  constructor() {
    // Los guards dependen del usuario: al cambiar de sesión o de selectores se vuelven a evaluar
    const user = this.appState.user('main');
    effect((onCleanup) => {
      user();
      const urls = this.candidates().flatMap((group) => group.links.map((link) => link.url));
      const subscription = new Subscription();
      this.allowed.set({});
      urls.forEach((url) =>
        subscription.add(
          this.access
            .checkRouteGuards(url)
            .subscribe((ok) => this.allowed.update((current) => ({ ...current, [url]: ok }))),
        ),
      );
      onCleanup(() => subscription.unsubscribe());
    });
  }
}

function present(value: unknown): boolean {
  return value !== undefined && value !== null && value !== '';
}
